  1→import { useState, useMemo, useRef, useEffect } from "react";
  2→import { cn } from "@/lib/utils";
  3→import { Plus, Clock, Loader2, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText } from "lucide-react";
  4→import { format } from "date-fns";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { SidebarInput } from "@/components/ui/sidebar";
  8→import { supabase } from "@/integrations/supabase/client";
  9→import { toast } from "sonner";
 10→import {
 11→  DropdownMenu,
 12→  DropdownMenuContent,
 13→  DropdownMenuItem,
 14→  DropdownMenuTrigger,
 15→} from "@/components/ui/dropdown-menu";
 16→import {
 17→  AlertDialog,
 18→  AlertDialogAction,
 19→  AlertDialogCancel,
 20→  AlertDialogContent,
 21→  AlertDialogDescription,
 22→  AlertDialogFooter,
 23→  AlertDialogHeader,
 24→  AlertDialogTitle,
 25→} from "@/components/ui/alert-dialog";
 26→import {
 27→  Sidebar,
 28→  SidebarContent,
 29→  SidebarHeader,
 30→  SidebarGroup,
 31→  SidebarGroupLabel,
 32→  SidebarGroupContent,
 33→  SidebarMenu,
 34→  SidebarMenuItem,
 35→  SidebarMenuButton,
 36→} from "@/components/ui/sidebar";
 37→
 38→interface PastJob {
 39→  id: string;
 40→  title: string | null;
 41→  job_description: string;
 42→  status: string;
 43→  created_at: string;
 44→  resume_count: number;
 45→}
 46→
 47→interface JobSidebarProps {
 48→  pastJobs: PastJob[];
 49→  selectedJobId: string | null;
 50→  loadingPastJobs: boolean;
 51→  onSelectJob: (jobId: string) => void;
 52→  onNewJob: () => void;
 53→  onRenameJob: (jobId: string, newTitle: string) => void;
 54→  onDeleteJob: (jobId: string) => void;
 55→  onAuthRequired?: () => void;
 56→  isAuthenticated?: boolean;
 57→}
 58→
 59→function getDisplayTitle(job: PastJob): string {
 60→  if (job.title) return job.title;
 61→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 62→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 63→}
 64→
 65→const JobSidebar = ({ pastJobs, selectedJobId, loadingPastJobs, onSelectJob, onNewJob, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
 66→  const [search, setSearch] = useState("");
 67→  const [editingId, setEditingId] = useState<string | null>(null);
 68→  const [editValue, setEditValue] = useState("");
 69→  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
 70→  const editInputRef = useRef<HTMLInputElement>(null);
 71→
 72→  const filteredJobs = useMemo(() => {
 73→    if (!search.trim()) return pastJobs;
 74→    const q = search.toLowerCase();
 75→    return pastJobs.filter(
 76→      (job) =>
 77→        getDisplayTitle(job).toLowerCase().includes(q) ||
 78→        job.job_description.toLowerCase().includes(q)
 79→    );
 80→  }, [pastJobs, search]);
 81→
 82→  useEffect(() => {
 83→    if (editingId && editInputRef.current) {
 84→      editInputRef.current.focus();
 85→      editInputRef.current.select();
 86→    }
 87→  }, [editingId]);
 88→
 89→  const startEditing = (job: PastJob) => {
 90→    setEditingId(job.id);
 91→    setEditValue(getDisplayTitle(job));
 92→  };
 93→
 94→  const saveRename = async () => {
 95→    if (!editingId || !editValue.trim()) {
 96→      setEditingId(null);
 97→      return;
 98→    }
 99→    try {
100→      const { error } = await supabase
101→        .from("jobs")
102→        .update({ title: editValue.trim() } as any)
103→        .eq("id", editingId);
104→      if (error) throw error;
105→      onRenameJob(editingId, editValue.trim());
106→      toast.success("Job renamed");
107→    } catch {
108→      toast.error("Failed to rename job");
109→    }
110→    setEditingId(null);
111→  };
112→
113→  const cancelEditing = () => setEditingId(null);
114→
115→  const confirmDelete = () => {
116→    if (deleteJobId) {
117→      onDeleteJob(deleteJobId);
118→      setDeleteJobId(null);
119→    }
120→  };
121→
122→  return (
123→    <>
124→      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
125→        <SidebarHeader className="p-4 space-y-3">
126→          <Button onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }} className="w-full gap-2" size="sm">
127→            <Plus className="h-4 w-4" />
128→            New Job
129→          </Button>
130→          <div className="relative">
131→            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
132→            <SidebarInput
133→              placeholder="Search jobs…"
134→              value={search}
135→              onChange={(e) => setSearch(e.target.value)}
136→              className="pl-8"
137→            />
138→          </div>
139→        </SidebarHeader>
140→
141→        <SidebarContent>
142→          <SidebarGroup>
143→            <SidebarGroupLabel className="px-4 flex items-center gap-2">
144→              <Briefcase className="h-4 w-4" />
145→              <span>Job History</span>
146→              {search && <span className="ml-auto text-[10px]">({filteredJobs.length})</span>}
147→            </SidebarGroupLabel>
148→            <SidebarGroupContent>
149→              {!isAuthenticated ? (
150→                <div className="px-3 py-3">
151→                  <button
152→                    onClick={() => onAuthRequired?.()}
153→                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
154→                  >
155→                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
156→                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
157→                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
158→                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
159→                      Sign in to get started →
160→                    </span>
161→                  </button>
162→                </div>
163→              ) : loadingPastJobs ? (
164→                <div className="flex items-center justify-center py-8">
165→                  <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
166→                </div>
167→              ) : filteredJobs.length === 0 ? (
168→                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
169→                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
170→                </p>
171→              ) : (
172→                <SidebarMenu className="space-y-1.5 px-2">
173→                  {filteredJobs.map((job) => (
174→                    <SidebarMenuItem key={job.id}>
175→                      {editingId === job.id ? (
176→                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
177→                          <Input
178→                            ref={editInputRef}
179→                            value={editValue}
180→                            onChange={(e) => setEditValue(e.target.value)}
181→                            onKeyDown={(e) => {
182→                              if (e.key === "Enter") saveRename();
183→                              if (e.key === "Escape") cancelEditing();
184→                            }}
185→                            onBlur={saveRename}
186→                            className="h-7 text-sm"
187→                          />
188→                        </div>
189→                      ) : (
190→                        <SidebarMenuButton
191→                          isActive={selectedJobId === job.id}
192→                          onClick={() => onSelectJob(job.id)}
193→                          className={cn(
194→                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
195→                            "rounded-lg border transition-colors",
196→                            selectedJobId === job.id
197→                              ? "border-l-2 border-l-primary bg-sidebar-accent"
198→                              : "border-transparent hover:bg-sidebar-accent/50"
199→                          )}
200→                        >
201→                          <div className="flex items-center gap-1 w-full">
202→                            <span className="text-sm leading-snug line-clamp-2 flex-1">
203→                              {getDisplayTitle(job)}
204→                            </span>
205→                            <DropdownMenu>
206→                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
207→                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
208→                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
209→                                </button>
210→                              </DropdownMenuTrigger>
211→                              <DropdownMenuContent align="end" className="w-36">
212→                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
213→                                  <Pencil className="h-3.5 w-3.5 mr-2" />
214→                                  Rename
215→                                </DropdownMenuItem>
216→                                <DropdownMenuItem
217→                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
218→                                  className="text-destructive focus:text-destructive"
219→                                >
220→                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
221→                                  Delete
222→                                </DropdownMenuItem>
223→                              </DropdownMenuContent>
224→                            </DropdownMenu>
225→                          </div>
226→                          <div className="flex items-center gap-2 w-full">
227→                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
228→                              <FileText className="h-2.5 w-2.5" />
229→                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
230→                            </span>
231→                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5 ml-auto">
232→                              <Clock className="h-2.5 w-2.5" />
233→                              {format(new Date(job.created_at), "MMM d, yyyy")}
234→                            </span>
235→                          </div>
236→                        </SidebarMenuButton>
237→                      )}
238→                    </SidebarMenuItem>
239→                  ))}
240→                </SidebarMenu>
241→              )}
242→            </SidebarGroupContent>
243→          </SidebarGroup>
244→        </SidebarContent>
245→      </Sidebar>
246→
247→      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
248→        <AlertDialogContent>
249→          <AlertDialogHeader>
250→            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
251→            <AlertDialogDescription>
252→              This will permanently delete this job and all its resumes. This action cannot be undone.
253→            </AlertDialogDescription>
254→          </AlertDialogHeader>
255→          <AlertDialogFooter>
256→            <AlertDialogCancel>Cancel</AlertDialogCancel>
257→            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
258→              Delete
259→            </AlertDialogAction>
260→          </AlertDialogFooter>
261→        </AlertDialogContent>
262→      </AlertDialog>
263→    </>
264→  );
265→};
266→
267→export default JobSidebar;
268→

  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import {
  9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
 10→  FileText, Archive
 11→} from "lucide-react";
 12→import { toast } from "sonner";
 13→import type { Result } from "@/pages/Index";
 14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 15→// Sub-components
 16→import CandidateSummary from "@/components/candidate/CandidateSummary";
 17→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 18→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 19→import EducationPanel from "@/components/candidate/EducationPanel";
 20→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 21→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 22→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 23→import StageTracker from "@/components/candidate/StageTracker";
 24→import type { HiringStage } from "@/hooks/useStageTracker";
 25→
 26→interface CandidateRowProps {
 27→  result: Result;
 28→  index: number;
 29→  isExpanded: boolean;
 30→  isSelected: boolean;
 31→  jobTitle?: string | null;
 32→  onToggleRow: (id: string) => void;
 33→  onToggleSelect: (resumeId: string) => void;
 34→  onDownload: (filePath: string, filename: string) => void;
 35→  onDelete: (resumeId: string, filePath: string | null) => void;
 36→  onDismiss: (resumeId: string) => void;
 37→  formatCandidateName: (filename: string) => string;
 38→  currentStage?: HiringStage | null;
 39→  stageUpdatedAt?: string | null;
 40→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 41→  onRewriteJd?: () => void;
 42→  isDuplicate?: boolean;
 43→}
 44→
 45→const getScoreColor = (score: number) => {
 46→  if (score >= 70) return "bg-score-skills";
 47→  if (score >= 40) return "bg-warning";
 48→  return "bg-destructive";
 49→};
 50→
 51→const getScoreTextColor = (score: number) => {
 52→  if (score >= 70) return "text-score-skills";
 53→  if (score >= 40) return "text-warning";
 54→  return "text-destructive";
 55→};
 56→
 57→const STAGE_BADGE_CLASSES: Record<string, string> = {
 58→  applied: "border-border bg-muted/50 text-muted-foreground",
 59→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 60→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 61→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 62→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 63→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 64→};
 65→
 66→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 67→  if (score >= 70) return { label: "Strong", variant: "success" };
 68→  if (score >= 40) return { label: "Good", variant: "warning" };
 69→  return { label: "Weak", variant: "destructive" };
 70→};
 71→
 72→const getRankDisplay = (index: number) => {
 73→  if (index < 3) {
 74→    const colors = [
 75→      "bg-score-overall text-white dark:text-white",
 76→      "bg-muted-foreground/60 text-white dark:text-white",
 77→      "bg-warning text-warning-foreground",
 78→    ];
 79→    return (
 80→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 81→        {index + 1}
 82→      </span>
 83→    );
 84→  }
 85→  return (
 86→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 87→      {index + 1}
 88→    </span>
 89→  );
 90→};
 91→
 92→const CandidateRow = ({
 93→  result: r,
 94→  index,
 95→  isExpanded,
 96→  isSelected,
 97→  jobTitle,
 98→  onToggleRow,
 99→  onToggleSelect,
100→  onDownload,
101→  onDelete,
102→  onDismiss,
103→  formatCandidateName,
104→  currentStage,
105→  stageUpdatedAt,
106→  onStageChange,
107→  onRewriteJd,
108→  isDuplicate,
109→}: CandidateRowProps) => {
110→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
111→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
112→
113→  return (
114→    <>
115→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
116→      <>
117→        {/* Collapsed Row */}
118→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
119→          <TableCell onClick={(e) => e.stopPropagation()}>
120→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
121→          </TableCell>
122→          <TableCell className="text-center">
123→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
124→          </TableCell>
125→          <TableCell className="font-medium">
126→            <div className="flex flex-col gap-0.5">
127→              <div className="flex items-center gap-1.5 flex-wrap">
128→                <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
129→                {isDuplicate && (
130→                  <TooltipProvider delayDuration={300}>
131→                    <Tooltip>
132→                      <TooltipTrigger asChild>
133→                        <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
134→                          Duplicate
135→                        </Badge>
136→                      </TooltipTrigger>
137→                      <TooltipContent side="top" className="max-w-xs text-xs">
138→                        This candidate appears to have been uploaded more than once. Consider removing the duplicate.
139→                      </TooltipContent>
140→                    </Tooltip>
141→                  </TooltipProvider>
142→                )}
143→                {!r.pending && currentStage && currentStage !== "applied" && (
144→                  <Badge
145→                    variant="outline"
146→                    className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
147→                  >
148→                    {currentStage}
149→                  </Badge>
150→                )}
151→              </div>
152→              {r.candidate_location && (
153→                <span className="flex items-center gap-1 text-xs text-muted-foreground">
154→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
155→                </span>
156→              )}
157→            </div>
158→          </TableCell>
159→          <TableCell>
160→            {r.pending ? (
161→              <Badge variant="outline" className="text-xs">Pending</Badge>
162→            ) : (
163→              <div className="flex items-center gap-2">
164→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
165→                  <div
166→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
167→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
168→                  />
169→                </div>
170→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
171→                  {r.overall_score?.toFixed(0)}%
172→                </span>
173→              </div>
174→            )}
175→          </TableCell>
176→          <TableCell>
177→            <div className="flex flex-wrap items-center gap-1">
178→              {!r.pending && strength && (
179→                <Badge variant={strength.variant} className="text-[10px]">
180→                  {strength.label}
181→                </Badge>
182→              )}
183→              {!r.pending && r.scoring_version === "heuristic" && (
184→                <TooltipProvider delayDuration={300}>
185→                  <Tooltip>
186→                    <TooltipTrigger asChild>
187→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
188→                        Quick
189→                      </span>
190→                    </TooltipTrigger>
191→                    <TooltipContent className="max-w-xs text-xs">
192→                      This candidate was ranked by keyword matching. Top candidates receive full AI scoring.
193→                    </TooltipContent>
194→                  </Tooltip>
195→                </TooltipProvider>
196→              )}
197→              {!r.pending && r.scoring_version?.startsWith("rule-") && (
198→                <TooltipProvider delayDuration={300}>
199→                  <Tooltip>
200→                    <TooltipTrigger asChild>
201→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 font-medium cursor-default">
202→                        Rule
203→                      </span>
204→                    </TooltipTrigger>
205→                    <TooltipContent className="max-w-xs text-xs">
206→                      Scored using deterministic rule-based algorithm. Same input always produces the same score.
207→                    </TooltipContent>
208→                  </Tooltip>
209→                </TooltipProvider>
210→              )}
211→            </div>
212→          </TableCell>
213→          <TableCell>
214→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
215→              <TooltipProvider delayDuration={300}>
216→                {/* Phone */}
217→                <Tooltip>
218→                  <TooltipTrigger asChild>
219→                    {r.candidate_phone ? (
220→                      <a
221→                        href={`tel:${r.candidate_phone}`}
222→                        onClick={(e) => {
223→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
224→                            e.preventDefault();
225→                            navigator.clipboard.writeText(r.candidate_phone!);
226→                            toast.success("Phone number copied!");
227→                          }
228→                        }}
229→                      >
230→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" aria-label="Call candidate">
231→                          <Phone className="h-3.5 w-3.5" />
232→                        </Button>
233→                      </a>
234→                    ) : (
235→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled aria-label="Phone not available">
236→                        <Phone className="h-3.5 w-3.5" />
237→                      </Button>
238→                    )}
239→                  </TooltipTrigger>
240→                  <TooltipContent>{r.candidate_phone ? `Copy: ${r.candidate_phone}` : "Phone not found in resume"}</TooltipContent>
241→                </Tooltip>
242→
243→                {/* Email */}
244→                <Tooltip>
245→                  <TooltipTrigger asChild>
246→                    {r.candidate_email ? (
247→                      <Button
248→                        variant="ghost"
249→                        size="icon"
250→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
251→                        onClick={() => setEmailDialogOpen(true)}
252→                        aria-label="Email candidate"
253→                      >
254→                        <Mail className="h-3.5 w-3.5" />
255→                      </Button>
256→                    ) : (
257→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled aria-label="Email not available">
258→                        <Mail className="h-3.5 w-3.5" />
259→                      </Button>
260→                    )}
261→                  </TooltipTrigger>
262→                  <TooltipContent>{r.candidate_email ? `Email: ${r.candidate_email}` : "Email not found in resume"}</TooltipContent>
263→                </Tooltip>
264→
265→                {/* Download */}
266→                <Tooltip>
267→                  <TooltipTrigger asChild>
268→                    {r.file_path ? (
269→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)} aria-label="Download resume">
